const fixtureFiles={"ready-current":"ready-current.json","ready-cached":"ready-cached.json","partial":"partial.json","not-run":"not-run.json","failed":"failed.json","stale-mixed":"stale-mixed.json","source-missing":"source-missing.json","agreements-conflicts":"agreements-conflicts.json","usage-null":"usage-null.json","warnings-multiple":"warnings-multiple.json","explicit-run-404":"explicit-run-404.json"};
const labels={ready:"READY / 当前",partial:"PARTIAL / 部分完成",not_run:"NOT RUN / 尚未运行",failed:"FAILED / 失败",stale:"STALE / 陈旧",source_missing:"SOURCE MISSING / 来源缺失"};
const safe=(v)=>String(v??"—"); const $=(s)=>document.querySelector(s); const text=(node,value)=>{node.textContent=safe(value);};
async function loadFixture(name){const r=await fetch(`../../fixtures/model_persona_panel_review/${fixtureFiles[name]}`);return r.json()}
function level(status){return status==="ready"?"ok":status==="not_run"||status==="source_missing"?"info":status==="failed"?"bad":"warning"}
function renderBanner(data){const b=$("#statusBanner");const status=data.review_status;const icon={ready:"◆",partial:"△",not_run:"○",failed:"×",stale:"◌",source_missing:"∅"}[status]||"!";b.dataset.level=level(status);b.innerHTML="";const i=document.createElement("span");i.className="status-icon";i.setAttribute("aria-hidden","true");i.textContent=icon;const wrap=document.createElement("div");const strong=document.createElement("strong");strong.textContent=labels[status]||"EXPLICIT RUN 404 / 未找到";const p=document.createElement("p");p.textContent=data.summary?.headline||"Panel run not found; context retained.";wrap.append(strong,p);b.append(i,wrap)}
function renderAuthority(data){const t=$("#authorityContent");t.innerHTML="";const p=data.authoritative_panel||{};const vals=[["OVERALL ENGAGEMENT",p.overall_engagement_score==null?"未提供":p.overall_engagement_score,"/ 100"],["RETENTION RISK",p.retention_risk||"未提供",""],["PANEL STATUS",p.panel_status||data.review_status||"未提供",""]];vals.forEach(([label,value,suffix])=>{const m=document.createElement("div");m.className="metric";const l=document.createElement("label");l.textContent=label;const st=document.createElement("strong");st.textContent=safe(value);if(suffix){const e=document.createElement("em");e.textContent=suffix;st.append(" ",e)}m.append(l,st);t.append(m)});const flags=Array.isArray(p.priority_flags)?p.priority_flags:[];if(flags.length){const f=document.createElement("div");f.className="flag-row";f.textContent="◆ 优先关注："+flags.map(x=>safe(x.flag_code)).join(" · ");t.append(f)}}
function renderPersonas(data){const t=$("#personaGrid");t.innerHTML="";const cards=(data.persona_reviews||[]).slice().sort((a,b)=>(a.persona_order||0)-(b.persona_order||0));text($("#personaCount"),cards.length?`${cards.length} 张卡片 · 固定权威顺序`:"暂无可展示卡片");if(!cards.length){const e=document.createElement("div");e.className="empty";e.textContent=data.review_status==="not_run"?"尚未生成 Persona 结果。":"当前状态没有可安全展示的 Persona 卡片。";t.append(e);return}cards.forEach(card=>{const a=card.authoritative||{},s=card.model_supplement||{};const article=document.createElement("article");article.className="persona-card";article.dataset.displayStatus=card.display_status||"";const order=document.createElement("span");order.className="persona-order";order.textContent=`0${card.persona_order||0}`;const badge=document.createElement("span");badge.className="badge";badge.textContent=safe(card.display_status);const h=document.createElement("h3");h.textContent=safe(card.persona_name);h.append(badge);const authority=document.createElement("div");authority.className="persona-authority";const al=document.createElement("span");al.className="label";al.textContent="AUTHORITATIVE / 权威读数";const score=document.createElement("span");score.className="score";score.textContent=a.engagement_score==null?"—":safe(a.engagement_score);const risk=document.createElement("span");risk.className="risk";risk.textContent=` / retention ${safe(a.retention_risk)}`;authority.append(al,score,risk);const supp=document.createElement("div");supp.className="supplement";const sl=document.createElement("span");sl.className="label";sl.textContent="MODEL SUPPLEMENT / 模型补充";const sp=document.createElement("p");sp.textContent=s.model_feedback||"暂无模型补充。";supp.append(sl,sp);article.append(order,h,authority,supp);t.append(article)})}
function listSignals(selector,items,kind){const t=$(selector);t.innerHTML="";if(!items?.length){const e=document.createElement("div");e.className="empty";e.textContent=kind==="agree"?"暂无检测到一致信号。":"暂无检测到分歧信号。";t.append(e);return}items.forEach(x=>{const d=document.createElement("div");d.className="signal-item";const s=document.createElement("strong");s.textContent=kind==="agree"?`≈ ${safe(x.category)} · ${safe(x.severity)}`:`≠ ${safe(x.conflict_type)} · unresolved`;const p=document.createElement("div");p.className="signal-meta";p.textContent=`Persona：${(x.persona_ids||[]).join("、")} · 位置：${safe(x.target_location)} · 证据：${(x.evidence_ids||[]).join("、")}`;d.append(s,p);t.append(d)})}
function auditRow(label,value){const d=document.createElement("div");d.className="audit-row";const s=document.createElement("span");s.textContent=label;const b=document.createElement("strong");b.textContent=safe(value);d.append(s,b);return d}
function renderAudit(data){const sel=$("#selection");sel.innerHTML="";[["run",data.selected_panel_execution_id||"未选择"],["reason",data.selection_reason||"—"],["status",data.selected_run_status||"—"],["staleness",data.selected_run_staleness||"—"]].forEach(([k,v])=>{const wrap=document.createElement("div");const dt=document.createElement("dt");dt.textContent=k;const dd=document.createElement("dd");dd.textContent=safe(v);wrap.append(dt,dd);sel.append(wrap)});const e=$("#execution");e.innerHTML="";const ex=data.execution_summary||{};[["completed",ex.completed_persona_count],["cached",ex.cached_persona_count],["blocked",ex.blocked_persona_count],["provider calls",`${ex.actual_provider_call_count??"—"} / ${ex.expected_provider_call_count??"—"}`]].forEach(x=>e.append(auditRow(x[0],x[1])));const ev=$("#evidence");ev.innerHTML="";const es=data.evidence_summary||{};[["coverage",es.coverage_status],["valid refs",es.valid_references],["unknown refs",es.unknown_references],["personas covered",es.covered_persona_count]].forEach(x=>ev.append(auditRow(x[0],x[1])));const u=$("#usage");u.innerHTML="";const us=data.usage_summary;u.append(auditRow("usage",us?us.usage_completeness:"未提供"));if(us){u.append(auditRow("total tokens",us.total_tokens),auditRow("duration",`${us.duration_ms} ms`))}const st=data.staleness_summary||{};u.append(auditRow("stale personas",st.stale_persona_count??"—"));const w=$("#warnings");w.innerHTML="";(data.warnings||["无结构化警告"]).forEach(x=>{const li=document.createElement("li");li.textContent=safe(x);w.append(li)})}
async function render(name){const data=await loadFixture(name);if(data.ok===false){renderBanner({review_status:"failed",summary:{headline:"Panel run not found · 保留章节上下文"},selected_panel_execution_id:null,selected_run_status:"404",selected_run_staleness:"not_run",warnings:data.errors});renderAuthority({review_status:"not_run",authoritative_panel:{}});renderPersonas({review_status:"not_run",persona_reviews:[]});renderAudit({selection_reason:"explicit_panel_execution_id",selected_panel_execution_id:"未找到",selected_run_status:"404",selected_run_staleness:"not_run",warnings:data.errors});return}renderBanner(data);renderAuthority(data);renderPersonas(data);listSignals("#agreementList",data.agreement_groups,"agree");listSignals("#conflictList",data.conflict_groups,"conflict");renderAudit(data);const u=new URL(location.href);u.searchParams.set("mode","simulator");u.searchParams.set("view","reader-panel-review");u.searchParams.set("project",data.project_id||"proj-demo");u.searchParams.set("timeline_id",data.timeline_id||"timeline-demo");u.searchParams.set("chapter_id",data.chapter_id||12);if(data.selected_panel_execution_id)u.searchParams.set("panel_execution_id",data.selected_panel_execution_id);$("#deepLink").href=u.toString();}
const select=$("#fixtureSelect");Object.keys(fixtureFiles).forEach(k=>{const o=document.createElement("option");o.value=k;o.textContent=k;select.append(o)});select.value="ready-current";select.addEventListener("change",()=>render(select.value));render("ready-current");
